  if (n <= 2) {
    return n === 2;
  }
  if (n % i === 0) {
    return false;
  }
  if (i * i > n) {
    return true;
  }
  return isPrime(n, i + 1);
}

function generatePrimes(n = 100) {
  if (n < 2) {
    return [];
  }
  const primes = generatePrimes(n - 1);
  if (isPrime(n)) {
    primes.push(n);
  }
  return primes;
}

